oxy_webhelp_navlinks = {"saphana_configure_protection-d39307e41053":{"topics":[{"title":"Creating a custom SLA Domain for SAP HANA","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain to streamline and customize protection and management         policies for your SAP HANA workloads.<\/p>","href":"saas\/saphana_creating_custom_sla.html","attributes":{"data-id":"saphana_creating_custom_sla"},"menu":{"hasChildren":false},"tocID":"saphana_creating_custom_sla-d39307e41064","topics":[]},{"title":"Assigning protection to SAP HANA","shortdesc":"<p class=\"shortdesc\">Assign an SLA Domain to SAP HANA systems or individual databases to apply data         protection and management policies to your SAP HANA workloads.<\/p>","href":"saas\/saphana_assigning_protection.html","attributes":{"data-id":"saphana_assigning_protection"},"menu":{"hasChildren":false},"tocID":"saphana_assigning_protection-d39307e41075","topics":[]},{"title":"Taking an on-demand snapshot of SAP HANA workloads","shortdesc":"<p class=\"shortdesc\">In addition to policy-based snapshots, use the on-demand snapshot process to take         backint snapshots of a SAP HANA database for full, incremental, and differential backups.         You can also take storage snapshots of an SAP HANA system for full backups.<\/p>","href":"saas\/sap_hana_taking_ods.html","attributes":{"data-id":"sap_hana_taking_ods"},"menu":{"hasChildren":false},"tocID":"sap_hana_taking_ods-d39307e41086","topics":[]},{"title":"Managing native backup compression for SAP HANA databases","shortdesc":"<p class=\"shortdesc\">Enable SAP HANA native backup compression at the database level to reduce backup size         and improve backup performance.<\/p>","href":"saas\/sap_hana_backup_compression.html","attributes":{"data-id":"sap_hana_backup_compression"},"menu":{"hasChildren":false},"tocID":"sap_hana_backup_compression-d39307e41097","topics":[]}]}};